typedef float rational_t;

class vector3d
{
public:
  float x, y, z;
  vector3d operator-(const vector3d &) const;
  rational_t length() const;
  vector3d &operator*=(rational_t);
};

template <class T> class vector
{
  T *start;
  T *finish;
  T *end_of_storage;
public:
  void push_back(const T &);
};

class path_graph_edge;

class path_graph_node
{
  vector3d pt;
  void *my_region;
  unsigned short flags;
  vector<path_graph_edge *> edges;
  friend class path_graph;
public:
  virtual ~path_graph_node();
  void add_edge(path_graph_edge *edge, bool sort = true);
};

class path_graph_edge
{
  path_graph_node *nodes[2];
  unsigned short flags;
  rational_t distance;
  rational_t weight_modifier;
  rational_t additional_weight_modifier;
  rational_t bias;
  vector3d direction;
  friend class path_graph;
public:
  path_graph_edge();
  virtual ~path_graph_edge();
};

class path_graph
{
  char id[8];
  vector<path_graph_node *> nodes;
  vector<path_graph_edge *> edges;
public:
  virtual ~path_graph();
  bool edge_in_graph(const path_graph_node *node1, const path_graph_node *node2) const;
  void add_edge(path_graph_node *node1, path_graph_node *node2, unsigned short flags, rational_t modifier);
};

void *operator new(unsigned int, unsigned int, const char *, int);

#define NULL 0
#define assert(x) ((void)0)
#define NEW new(0, __PRETTY_FUNCTION__, 0)

void path_graph::add_edge(path_graph_node *node1, path_graph_node *node2, unsigned short flags, rational_t modifier)
{
  assert(node1 != NULL && node2 != NULL);

  if(!edge_in_graph(node1, node2))
  {
    path_graph_edge *edge = NEW path_graph_edge();

    edge->nodes[0] = node1;
    edge->nodes[1] = node2;
    edge->direction = (edge->nodes[1]->pt - edge->nodes[0]->pt);
    edge->distance = edge->direction.length();

    assert(edge->distance > 0.0f);

    edge->direction *= (1.0f / edge->distance);

    edge->flags = flags;
    edge->weight_modifier = modifier;

    edge->nodes[0]->add_edge(edge, true);
    edge->nodes[1]->add_edge(edge, true);

    edges.push_back(edge);
  }
}
